import{_ as t}from"./chunks/hub.pc.ko.D5LMmVxq.js";import{_ as e}from"./chunks/hub-robots.pc.ko.CAIeCjT8.js";import{_ as i}from"./chunks/home-status.pc.ko.4ClbLxoN.js";import{_ as a,o as r,c as n,a5 as s}from"./chunks/framework.BjM_ivYE.js";const c="/RBQ/images/app/boot-prestart.pc.ko.png",l="/RBQ/images/app/boot-autostart-confirm.pc.ko.png",d="/RBQ/images/app/boot-autostart-running.pc.ko.png",y=JSON.parse('{"title":"컨트롤러와 Wi-Fi 연결","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/controller-wifi-connect.md","filePath":"ko/manual/operation/controller-wifi-connect.md","lastUpdated":1790652849000}'),p={name:"ko/manual/operation/controller-wifi-connect.md"};function g(m,o,u,h,f,b){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="컨트롤러와-wi-fi-연결" tabindex="-1">컨트롤러와 Wi-Fi 연결 <a class="header-anchor" href="#컨트롤러와-wi-fi-연결" aria-label="Permalink to &quot;컨트롤러와 Wi-Fi 연결&quot;">​</a></h1><p>컨트롤러(Steam Deck·태블릿·PC)를 로봇 Wi-Fi에 붙이고, RBQ 앱을 로봇에 연결한 뒤 자동 기동까지 마치는 절차입니다. 초기 자세와 전원은 먼저 <a href="./initial-pose.html">로봇 초기 자세 설정</a>에서 끝내 두세요.</p><h2 id="_1단계-앱-열기" tabindex="-1">1단계: 앱 열기 <a class="header-anchor" href="#_1단계-앱-열기" aria-label="Permalink to &quot;1단계: 앱 열기&quot;">​</a></h2><p>컨트롤러에서 <strong>RBQ</strong> 앱을 실행합니다. Steam Deck에 앱을 아직 설치하지 않았다면 <a href="/RBQ/ko/manual/troubleshooting/steamdeck-setup.html">Steam Deck 설정</a>을 먼저 보세요. 설치 파일은 <a href="/RBQ/ko/manual/downloads/">다운로드</a>에 있습니다.</p><h2 id="wifi" tabindex="-1">2단계: 로봇 Wi-Fi에 붙기 <a class="header-anchor" href="#wifi" aria-label="Permalink to &quot;2단계: 로봇 Wi-Fi에 붙기 {#wifi}&quot;">​</a></h2><p>로봇은 <code>RBQ_{XX}</code>(XX는 기기마다 다름) 이름의 Wi-Fi 접속 지점을 냅니다. 컨트롤러를 이 망에 연결해야 로봇에 닿습니다.</p><p>앱을 켜면 <strong>허브</strong>가 나옵니다. 왼쪽 위에 로봇 이름이, 그 뒤에 연결 상태가 붙는데 이 상태줄이 지금 망이 맞는지 알려 줍니다.</p><p><img src="'+t+'" alt="허브 — 로봇 이름과 상태줄"></p><ol><li><strong>상태줄 읽기</strong> — <code>로봇 WiFi에 연결하세요</code>는 저장된 로봇이 아직 없다는 뜻이고, <code>로봇 WiFi가 아닙니다</code>는 이 기기가 다른 망에 있다는 뜻입니다. 앱이 로봇의 WiFi를 알고 있으면 어느 망으로 바꿀지까지 표시합니다(<em>로봇 WiFi(SSID)로 바꿔 주세요</em>).</li><li><strong>망 바꾸기</strong> — Linux 데스크탑과 Steam Deck에서는 상태줄 옆의 <code>WiFi 전환</code> 버튼이 그 망에 바로 붙거나 앱 안의 망 목록을 열어 <code>RBQ_{XX}</code>를 고르게 해 줍니다. 비밀번호가 필요한 망이면 그 자리에서 입력합니다. Android에서는 <code>WiFi 설정</code>이 시스템 Wi-Fi 화면을 엽니다.</li><li><strong>연결 확인</strong> — 로봇 이름 앞의 점이 초록으로 바뀌면 됩니다.</li></ol><p>목록에 <code>RBQ_{XX}</code>가 보이지 않으면 로봇 전원과 Wi-Fi 동작 상태를 확인하세요.</p><p>제어 홈에 들어가면 상단 바의 WiFi 칩이 신호 세기를 보여 줍니다. 탭하면 <strong>내 기기 WiFi</strong>가 열려 지금 붙어 있는 망 이름과 <code>로봇 망</code>(초록) · <code>로봇 망 아님</code>(주황) 배지를 확인할 수 있습니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>Android는 정책상 앱 안에서 망을 검색할 수 없어 <strong>시스템 WiFi 설정</strong> 버튼만 있습니다. iOS와 브라우저(웹) 빌드도 Wi-Fi를 읽거나 바꾸지 못하니 기기의 Wi-Fi 설정에서 직접 붙으세요.</p></div></div><h2 id="connect" tabindex="-1">3단계: 로봇에 연결 <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;3단계: 로봇에 연결 {#connect}&quot;">​</a></h2><p>로봇은 허브에서 고르고 추가합니다. 설정 안에는 연결 화면이 없습니다.</p><ol><li><strong>로봇 이름(▾)을 탭</strong>하면 <strong>로봇 선택</strong>이 열립니다. 이 기기에 저장된 로봇과, 로그인 중이면 계정에 배정된 로봇이 함께 나옵니다.</li><li><strong>로봇 줄을 탭</strong>하면 연결합니다. Linux 데스크탑과 Steam Deck에서는 로봇의 WiFi가 저장되어 있고 주변에 보이면 먼저 그 망으로 옮긴 뒤 붙습니다.</li><li><strong>처음 쓰는 로봇</strong>이면 <code>로봇 추가</code>를 누릅니다. 로봇 AP에 붙어 있으면 앱이 고정 주소 <code>192.168.0.10</code>에서 스스로 찾고, <code>다시 확인</code>으로 다시 시도합니다. 공유기 아래에 있거나 공인 주소로 닿는 로봇은 <strong>주소로 연결</strong>(<code>로봇 IP</code> — 기본값 <code>192.168.0.10</code>, 또는 <code>공인 IP</code>)에서 추가하고, <code>접근 코드 입력</code>은 계정에 배정된 로봇을 원격(LTE)으로 쓰도록 등록합니다.</li><li><strong>통신이 열린 것</strong>은 점이 초록이 되고 상태줄이 <code>연결됨</code>과 경로를 보일 때입니다.</li></ol><p><img src="'+e+'" alt="로봇 선택"></p><p>경로의 차이, 앱을 켤 때의 자동 연결, 각 상태줄의 의미는 <a href="/RBQ/ko/manual/gui/connection.html">연결</a>에 정리되어 있습니다.</p><h2 id="auto-start" tabindex="-1">4단계: 자동 기동 <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;4단계: 자동 기동 {#auto-start}&quot;">​</a></h2><p>로봇 소프트웨어와 상태를 한 번에 올리는 절차입니다.</p><ol><li><strong>자동 기동 누르기</strong> — 기동 전에는 허브의 로봇 상태 아래와 제어 홈 가운데 아래에 <code>자동 기동</code> 버튼이 떠 있습니다. (허브 카드는 로봇이 연결돼야 나타나고, 제어 홈 알약은 그 전에도 있지만 회색입니다.)</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+c+'" alt="기동 전 홈 화면의 자동 기동 버튼" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 기동 전 홈 화면 ]</figcaption></figure><ol start="2"><li><strong>확인</strong> — 확인 창이 뜹니다. 로봇이 평평한 바닥에 있고 모든 발과 무릎이 지면에 닿아 있는지 확인한 뒤 <code>자동 기동</code>을 누릅니다. 창 가운데 줄은 앞으로 거칠 단계입니다 — <code>POWER</code> · <code>CAN-BUS</code> · <code>HOMING</code> · <code>IMU-CHECK</code> · <code>START</code>.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+l+'" alt="자동 기동 확인 창" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 자동 기동 확인 ]</figcaption></figure><ol start="3"><li><strong>진행 확인</strong> — 같은 창이 <strong>기동 시퀀스</strong>로 바뀌어 단계별 결과를 보여 줍니다. 다리·관절별 점검 결과와 걸린 시간이 함께 나오므로, 실패했을 때 어느 관절인지 바로 알 수 있습니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+d+'" alt="자동 기동 진행 중" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 자동 기동 진행 ]</figcaption></figure><ol start="4"><li><strong>완료 확인</strong> — 모든 항목이 완료로 바뀌고 로봇이 서면 기동이 끝난 것입니다. 상단 바의 상태를 누르면 항목별 결과를 다시 볼 수 있습니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+i+'" alt="기동 완료 후 상태 팝오버" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 기동 완료 — 상태 확인 ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>자동 기동이 끝나지 않거나 실패한 항목이 남으면, 주변에 사람이 없는지 확인한 뒤 <a href="/RBQ/ko/manual/safety/emergency-stop-procedures">비상 정지 절차</a>를 숙지하고 아래를 따르세요. 작동 전에는 <a href="/RBQ/ko/manual/safety/general-safety-warning-precautions">일반 안전 수칙</a>을 반드시 준수하세요.</p><ol style="margin:0.5rem 0 0 1.25rem;"><li>통신 점검이 실패한 경우: 로봇 전원을 안전하게 끈 뒤 재시작하세요.</li><li>홈 자세 찾기가 실패한 경우: <a href="/RBQ/ko/manual/safety/maintenance-safety">유지보수 안전</a>에 따라 평탄·안정된 면에서 다리 자세를 확인한 후 재시작하세요.</li></ol><p style="margin-top:0.75rem;">문제가 계속되면 <a href="/RBQ/ko/manual/support/">문의하기</a> 페이지에서 안내에 따라 Rainbow Robotics에 연락하세요.</p></div></div>',28)])])}const W=a(p,[["render",g]]);export{y as __pageData,W as default};
